"""Rebuild the audited open-data extract and deterministic synthetic baseline anchors.
Source files are immutable inputs. No network access or external Python packages required.
"""
import csv, hashlib, json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
raw=ROOT/'data/sources/uci-maternal-health-risk.csv'
rows=list(csv.DictReader(raw.open(encoding='utf-8-sig',newline='')))
eligible=[]
for index,r in enumerate(rows,1):
    age,sys,dia,hr=map(float,[r['Age'],r['SystolicBP'],r['DiastolicBP'],r['HeartRate']])
    if 18<=age<=45 and 90<=sys<140 and 60<=dia<90 and 60<=hr<=110 and 97<=float(r['BodyTemp'])<100.4:
        eligible.append({'row':index,'age':int(age),'systolic':int(sys),'diastolic':int(dia),'bloodSugarMmolL':float(r['BS']),'temperatureF':float(r['BodyTemp']),'heartRate':int(hr),'sourceRiskLabel':r['RiskLevel']})
# Unique observed tuples avoid duplicating the same baseline 15 times; no source label controls triage.
unique={}
for r in eligible:
    key=tuple(v for k,v in r.items() if k!='row')
    unique.setdefault(key,r)
seed='carebridge-open-baselines-v1'
selected=sorted(unique.values(),key=lambda r:hashlib.sha256(f"{seed}:{r['row']}".encode()).hexdigest())[:15]
benchmarks=list(csv.DictReader((ROOT/'data/sources/prams-2022-reference.csv').open()))
for r in benchmarks:
    for k in ['weightedPercent','lower95','upper95']:r[k]=float(r[k])
    for k in ['unweightedNumerator','unweightedDenominator','year','row']:r[k]=int(r[k])
out={'version':seed,'retrieved':'2026-11-08','uci':{'title':'Maternal Health Risk','doi':'https://doi.org/10.24432/C5DP5D','url':'https://archive.ics.uci.edu/dataset/863/maternal+health+risk','creator':'Ahmed, M. (2020)','license':'CC BY 4.0','population':'Pregnancy observations from rural Bangladesh; not a US postpartum cohort','sha256':hashlib.sha256(raw.read_bytes()).hexdigest(),'observedRows':len(rows),'catalogRows':1013,'eligibleRows':len(eligible),'uniqueEligibleRows':len(unique),'selection':'Adults 18–45; baseline BP 90–139/60–89, pulse 60–110, temperature 97–100.3°F; deduplicate tuples then SHA-256 seed ordering. This selected baseline sample is not prevalence representative.','anchors':selected},'prams':{'title':'CDC PRAMS MCH Indicators 2022','url':'https://www.cdc.gov/prams/media/files/2024/08/PRAMS-MCH-Indicators-2022-508.xlsx','population':'Participating 2022 PRAMS sites meeting the response threshold; not all US births and not Mississippi-specific','sha256':(ROOT/'data/sources/prams-2022-workbook.sha256').read_text().strip(),'benchmarks':benchmarks}}
(ROOT/'app/src/data/openData.ts').write_text('// Generated by scripts/build_open_data.py. Do not edit values manually.\nexport const OPEN_DATA = '+json.dumps(out,indent=2,ensure_ascii=False)+' as const;\n')
print(f"UCI: {len(rows)} parsed observations, {len(unique)} unique eligible baselines; {len(selected)} selected. PRAMS: {len(benchmarks)} indicators.")
